from fig_helpers_g123 import table_fig, bars_fig, fig_shape, fig_clock


def _q(b, num, d, p, ok, wrongs, e, s='', h='', fig=None):
    return make_q(f'TA3-B{b:02d}-{num:03d}', d, p, ok, wrongs, e, s, h, fig)


